fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Ceiling division: ceil(health / strength) = (health + strength - 1) / strength
    let h = health as i64;
    let s = strength as i64;
    (h + s - 1) / s
}

fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    let turns_takahashi = exec_turns_to_defeat(c, b); // hits to reduce Aoki's health to 0 or less
    let turns_aoki = exec_turns_to_defeat(a, d);      // hits to reduce Takahashi's health to 0 or less

    if turns_takahashi <= turns_aoki {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

